def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if not local or "." not in domain:
            return ""
        if domain.startswith(".") or domain.endswith("."):
            return ""

        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"
            if not local:
                return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = value or ""
        extension = re.search(r"(?:ext|x|#)", value, flags=re.IGNORECASE)
        if extension:
            value = value[:extension.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = (value or "").strip()

        if re.fullmatch(r"\d{5}-\d{4}", value):
            value = value.split("-", 1)[0]

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return (value or "").strip().lower() in {
            "y", "yes", "true", "1"
        }

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value or "")
            if tag.strip()
        }

    normalized_rows = []

    for input_index, row in enumerate(rows):
        normalized = {
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": normalize_email(row.get("email", "")),
            "phone": normalize_phone(row.get("phone", "")),
            "zip": normalize_zip(row.get("zip", "")),
            "tags": normalize_tags(row.get("tags", "")),
            "opted_out": is_opted_out(row.get("opted_out", "")),
            "updated_dt": parse_updated(row["updated"]),
            "source": (row.get("source", "") or "").strip().lower(),
            "input_index": input_index,
        }

        # Rows without either usable contact method do not participate at all.
        if normalized["email"] or normalized["phone"]:
            normalized_rows.append(normalized)

    count = len(normalized_rows)
    parent = list(range(count))
    rank = [0] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    by_email = {}
    by_phone_and_last_name = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            prior = by_email.get(row["email"])
            if prior is None:
                by_email[row["email"]] = index
            else:
                union(index, prior)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            prior = by_phone_and_last_name.get(key)
            if prior is None:
                by_phone_and_last_name[key] = index
            else:
                union(index, prior)

    groups = {}
    for index in range(count):
        groups.setdefault(find(index), []).append(index)

    def pick_value(group, field):
        candidates = [
            normalized_rows[index]
            for index in group
            if normalized_rows[index][field]
        ]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        group.sort(key=lambda i: normalized_rows[i]["input_index"])
        group_rows = [normalized_rows[i] for i in group]

        tags = set()
        for row in group_rows:
            tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group_rows)

        output.append({
            "first_name": pick_value(group, "first_name"),
            "last_name": pick_value(group, "last_name"),
            "zip": pick_value(group, "zip"),
            "email": pick_value(group, "email"),
            "phone": pick_value(group, "phone"),
            "source": pick_value(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group_rows) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
            "_earliest_index": group_rows[0]["input_index"],
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
